document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[el.dataset.icon]}</svg>`);
document.getElementById('year').textContent=new Date().getFullYear();
const menu=document.getElementById('menu'),nav=document.querySelector('nav');menu.onclick=()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close menu':'Open menu');};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');});
const hero=document.getElementById('heroVideo'),pause=document.getElementById('pause');function updatePause(){pause.textContent=hero.paused?'▷':'Ⅱ';pause.setAttribute('aria-label',hero.paused?'Play background video':'Pause background video');}pause.onclick=()=>{if(hero.paused)hero.play().catch(()=>{});else hero.pause();};hero.addEventListener('play',updatePause);hero.addEventListener('pause',updatePause);if(matchMedia('(prefers-reduced-motion: reduce)').matches){hero.autoplay=false;hero.pause();updatePause();}
const portfolio=[{id:4,title:'White & botanical',tag:'FLORAL INSTALLATIONS'},{id:0,title:'A softer kind of luxury',tag:'TABLESCAPES & FLORALS'},{id:13,title:'Warmth in every detail',tag:'CEREMONY STYLING'},{id:14,title:'Under a canopy of beauty',tag:'RECEPTION STYLING'},{id:9,title:'A little colour. A lot of joy.',tag:'CELEBRATION DETAILS'},{id:5,title:'The glow of candlelight',tag:'TABLE STYLING'},{id:6,title:'Golden beginnings',tag:'CEREMONY BACKDROPS'},{id:8,title:'Room for a beautiful moment',tag:'RECEPTION SPACES'},{id:1,title:'A personal touch',tag:'INTIMATE CELEBRATIONS'},{id:2,title:'Set with love',tag:'TABLESCAPES'},{id:3,title:'Through the drapes',tag:'EVENT SPACES'},{id:7,title:'A welcome to remember',tag:'WELCOME DETAILS'},{id:10,title:'The first impression',tag:'ENTRANCE STYLING'},{id:11,title:'A beautiful aisle',tag:'CEREMONY SPACES'},{id:12,title:'Colour & character',tag:'CELEBRATION BACKDROPS'}];
const gallery=document.getElementById('gallery'),film=document.getElementById('filmModal'),filmVideo=film.querySelector('video');portfolio.forEach((item,i)=>{const button=document.createElement('button');button.className='gallery-card';button.hidden=i>=4;button.setAttribute('aria-label',`Watch ${item.title}`);button.innerHTML=`<div class="photo"><img src="assets/event-${item.id}.jpg" alt="${item.title} — KR EVENTS styling" loading="lazy"><span class="play" aria-hidden="true">▶</span></div><h3>${item.title}</h3><p>${item.tag}</p>`;button.onclick=()=>{filmVideo.src=`assets/event-${item.id}.mp4`;document.getElementById('filmTitle').textContent=item.title;film.showModal();filmVideo.play().catch(()=>{});};gallery.append(button);});document.getElementById('moreWork').onclick=function(){const expand=this.textContent.includes('Discover');gallery.querySelectorAll('button').forEach((el,i)=>el.hidden=!expand&&i>=4);this.textContent=expand?'Show selected work':'Discover more of our work';};
document.querySelectorAll('dialog').forEach(dialog=>{dialog.querySelector('.close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});});film.addEventListener('close',()=>{filmVideo.pause();filmVideo.removeAttribute('src');filmVideo.load();});
const booking=document.getElementById('booking'),form=document.getElementById('bookingForm'),next=document.getElementById('next'),back=document.getElementById('back'),send=document.getElementById('send'),error=document.getElementById('formError');let step=0;
const occasions=['Wedding','Introduction / traditional ceremony','Birthday','Kids’ party','Private celebration','Other event'];const options=document.getElementById('occasionOptions');occasions.forEach((value,i)=>{const label=document.createElement('label'),input=document.createElement('input');input.type='radio';input.name='occasion';input.value=value;label.append(input,document.createTextNode(value));options.append(label);});
const localDate=new Intl.DateTimeFormat('en-CA',{timeZone:'Africa/Kampala',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());document.getElementById('eventDate').min=localDate;
function go(n){step=n;error.textContent='';document.querySelectorAll('.form-step').forEach(el=>el.hidden=Number(el.dataset.step)!==n);document.querySelectorAll('.progress span').forEach((el,i)=>el.classList.toggle('active',i<=n));back.hidden=n===0;next.hidden=n===2;send.hidden=n!==2;if(n===2)document.getElementById('review').textContent=summary(false);booking.scrollTop=0;}
function openBooking(occasion){if(occasion){const radio=[...form.elements.occasion].find(el=>el.value===occasion);if(radio)radio.checked=true;}go(0);booking.showModal();}document.querySelectorAll('.book').forEach(b=>b.onclick=()=>openBooking());document.querySelectorAll('[data-occasion]').forEach(b=>b.onclick=()=>openBooking(b.dataset.occasion));
function data(){return new FormData(form);}function formattedDate(value){return value?new Date(value+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'}):'To be decided';}
function summary(contact){const d=data();const lines=['*KR EVENTS — EVENT ENQUIRY*','',`*Occasion:* ${d.get('occasion')||'Other event'}`,`*Date:* ${formattedDate(d.get('date'))}`,`*Guests:* ${d.get('guests')||'To be decided'}`,`*Venue / location:* ${d.get('venue')?.trim()||'To be decided'}`,`*Styling budget:* ${d.get('budget')||'To be discussed'}`];if(d.get('ideas')?.trim())lines.push('',`*Ideas / requirements:*\n${d.get('ideas').trim()}`);if(contact)lines.push('','*CONTACT DETAILS*',`*Name:* ${d.get('name').trim()}`,`*Phone:* ${d.get('phone').trim()}`,'','Please let me know your availability and the next steps. Thank you!');return lines.join('\n');}
next.onclick=()=>{if(step===0&&!data().get('occasion')){error.textContent='Please choose an occasion to continue.';return;}if(step===1){const date=form.elements.date,guests=form.elements.guests;if(!date.checkValidity()){date.reportValidity();return;}if(!guests.checkValidity()){guests.reportValidity();return;}}go(step+1);};back.onclick=()=>go(step-1);
form.addEventListener('submit',e=>{e.preventDefault();if(!form.elements.name.value.trim()){error.textContent='Please enter your name.';form.elements.name.focus();return;}if(!form.reportValidity())return;const url='https://wa.me/256758975834?text='+encodeURIComponent(summary(true));const opened=window.open(url,'_blank','noopener,noreferrer');showToast('Your enquiry is ready in WhatsApp. Tap Send there to contact KR EVENTS.');});
let toastTimer;function showToast(message){const toast=document.getElementById('toast');toast.textContent=message;toast.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.style.display='none',6000);}document.querySelectorAll('.unavailable').forEach(button=>button.onclick=()=>showToast(button.dataset.icon==='instagram'?'Our Instagram details will be available soon.':'Our email address will be available soon.'));
